#include "ENGINE/Source/BlpFile/blp.h"
#include "ENGINE/Source/Base/status.h"

#include <algorithm>
#include <cstdlib>
#include <cstring>
#include <fstream>

namespace {
constexpr std::uint32_t kBlp2=0x32504C42u;
unsigned Levels(unsigned w,unsigned h){unsigned n=1;while(w>1||h>1){w=std::max(1u,w>>1);h=std::max(1u,h>>1);++n;}return std::min(n,16u);}
std::uint8_t Alpha(const BLPHeader&h,const std::uint8_t*a,unsigned i){switch(h.alphaSize){case 0:return 255;case 1:return (a[i>>3]&(1u<<(i&7)))?255:0;case 4:{std::uint8_t v=(a[i>>1]>>((i&1)*4))&15;return static_cast<std::uint8_t>(v*17);}default:return a[i];}}
}

CBLPFile::CBLPFile():m_images(nullptr),m_inMemoryImage(nullptr),m_inMemoryNeedsFree(0),m_numLevels(0),m_quality(100),m_colorMapping(nullptr),m_mipMapAlgorithm(MMA_BOX),m_lockDecompMem(nullptr){std::memset(&m_header,0,sizeof(m_header));m_header.magic=kBlp2;m_header.formatVersion=1;}
CBLPFile::~CBLPFile(){Close();}
void CBLPFile::Close(){if(m_lockDecompMem)std::free(m_lockDecompMem);m_lockDecompMem=nullptr;m_mipEntries.clear();m_ownedMips.clear();m_fileStorage.clear();m_images=nullptr;m_inMemoryImage=nullptr;m_inMemoryNeedsFree=0;m_numLevels=0;std::memset(&m_header,0,sizeof(m_header));m_header.magic=kBlp2;m_header.formatVersion=1;}
int IsLegalDimension(unsigned v){return v&&v<=0x10000u&&(v&(v-1))==0;}
int CBLPFile::CreateMipLevels(unsigned w,unsigned h){if(!IsLegalDimension(w)||!IsLegalDimension(h))return 0;m_numLevels=Levels(w,h);m_mipEntries.resize(m_numLevels);m_ownedMips.resize(m_numLevels);for(unsigned i=0;i<m_numLevels;++i){unsigned mw=std::max(1u,w>>i),mh=std::max(1u,h>>i);m_ownedMips[i].resize(static_cast<size_t>(mw)*mh);m_mipEntries[i].mip[0]=m_ownedMips[i].data();}m_images=m_mipEntries.data();return 1;}
int CBLPFile::Open(const char*f){if(!f)return 0;std::ifstream s(f,std::ios::binary|std::ios::ate);if(!s)return 0;auto n=s.tellg();if(n<static_cast<std::streamoff>(sizeof(BLPHeader)))return 0;std::vector<std::uint8_t> bytes(static_cast<size_t>(n));s.seekg(0);if(!s.read(reinterpret_cast<char*>(bytes.data()),n))return 0;Close();m_fileStorage=std::move(bytes);return Source(m_fileStorage.data(),static_cast<unsigned>(m_fileStorage.size()));}
int CBLPFile::Open(SFile*filename){return Open(reinterpret_cast<const char*>(filename));}
int CBLPFile::Source(void*bits){return Source(bits,~0u);}
int CBLPFile::Source(const void*bits,unsigned bytes){if(!bits||bytes<sizeof(BLPHeader))return 0;BLPHeader h{};std::memcpy(&h,bits,sizeof(h));if(h.magic!=kBlp2||!IsLegalDimension(h.width)||!IsLegalDimension(h.height)||h.colorEncoding<1||h.colorEncoding>2)return 0;for(unsigned i=0;i<16;++i)if(h.mipSizes[i]&&(h.mipOffsets[i]<sizeof(BLPHeader)||(bytes!=~0u&&(h.mipOffsets[i]>bytes||h.mipSizes[i]>bytes-h.mipOffsets[i]))))return 0;m_header=h;m_inMemoryImage=const_cast<void*>(bits);m_inMemoryNeedsFree=0;m_numLevels=1;while(m_numLevels<16&&h.mipSizes[m_numLevels]&&h.hasMips)m_numLevels++;return 1;}
C4Pixel*CBLPFile::Image(unsigned l){return m_images&&IsValidMip(l)?m_images[l].mip[0]:nullptr;}
int CBLPFile::SetImage(CBLPFile*s,unsigned l,CStatus*st){if(!s||!s->Image(l)){if(st)st->Add(STATUS_FATAL,"Tried to copy missing mip %u",l);return 0;}return SetImage(s->Image(l),std::max(1u,s->m_header.width>>l),std::max(1u,s->m_header.height>>l),s->m_header.alphaSize,l,st);}
int CBLPFile::SetImage(const void*p,unsigned w,unsigned h,std::uint8_t alpha,unsigned l,CStatus*st){if(!p||!IsLegalDimension(w)||!IsLegalDimension(h)||alpha>8){if(st)st->Add(STATUS_FATAL,"Invalid BLP image dimensions or alpha depth");return 0;}if(l==0){m_header.width=w;m_header.height=h;m_header.alphaSize=alpha;if(!m_images&&!CreateMipLevels(w,h))return 0;}if(!m_images||l>=m_numLevels)return 0;unsigned ew=std::max(1u,m_header.width>>l),eh=std::max(1u,m_header.height>>l);if(w!=ew||h!=eh){if(st)st->Add(STATUS_FATAL,"Expected %ux%u mip %u, received %ux%u",ew,eh,l,w,h);return 0;}std::memcpy(m_images[l].mip[0],p,static_cast<size_t>(w)*h*4);return 1;}
int CBLPFile::SetAlphaBits(unsigned a){if(a>8)return 0;m_header.alphaSize=static_cast<std::uint8_t>(a);return 1;}int CBLPFile::IsValidMip(unsigned l)const{return l==0||(m_header.hasMips!=MIPS_NONE&&l<m_numLevels);}MIPS_TYPE CBLPFile::HasMips()const{return static_cast<MIPS_TYPE>(m_header.hasMips);}void CBLPFile::SetHasMips(MIPS_TYPE m){m_header.hasMips=static_cast<std::uint8_t>(m);}
BlitFormat GetBlitFormat(PIXEL_FORMAT f){static constexpr BlitFormat map[]={BlitFormat_Dxt1,BlitFormat_Dxt3,BlitFormat_Argb8888,BlitFormat_Argb1555,BlitFormat_Argb4444,BlitFormat_Rgb565,BlitFormat_Unknown,BlitFormat_Dxt5,BlitFormat_Unknown};return f<NUM_PIXEL_FORMATS?map[f]:BlitFormat_Unknown;}
int CBLPFile::GetFormatSize(PIXEL_FORMAT f,unsigned l,unsigned*size,unsigned*stride)const{unsigned w=std::max(1u,m_header.width>>l),h=std::max(1u,m_header.height>>l),bpp=f==PIXEL_ARGB8888?4:(f>=PIXEL_ARGB1555&&f<=PIXEL_RGB565?2:0);if(!bpp){if(size)*size=0;if(stride)*stride=0;return 0;}if(size)*size=w*h*bpp;if(stride)*stride=w*bpp;return 1;}
void CBLPFile::DecompPalARGB8888(std::uint8_t*d,const std::uint8_t*s,unsigned n)const{const auto*a=s+n;for(unsigned i=0;i<n;++i){C4Pixel p=m_header.extended.palette[s[i]];p.a=Alpha(m_header,a,i);std::memcpy(d+i*4,&p,4);}}
void CBLPFile::DecompPalFastPath(std::uint8_t*d,const std::uint8_t*s,unsigned n)const{DecompPalARGB8888(d,s,n);}
void CBLPFile::DecompPalARGB4444(std::uint8_t*d,const std::uint8_t*s,unsigned n)const{std::vector<C4Pixel>p(n);DecompPalARGB8888(reinterpret_cast<std::uint8_t*>(p.data()),s,n);for(unsigned i=0;i<n;++i){std::uint16_t v=(p[i].b>>4)|((p[i].g>>4)<<4)|((p[i].r>>4)<<8)|((p[i].a>>4)<<12);std::memcpy(d+i*2,&v,2);}}
void CBLPFile::DecompPalARGB1555(std::uint8_t*d,const std::uint8_t*s,unsigned n)const{std::vector<C4Pixel>p(n);DecompPalARGB8888(reinterpret_cast<std::uint8_t*>(p.data()),s,n);for(unsigned i=0;i<n;++i){std::uint16_t v=(p[i].b>>3)|((p[i].g>>3)<<5)|((p[i].r>>3)<<10)|(p[i].a>=128?0x8000:0);std::memcpy(d+i*2,&v,2);}}
void CBLPFile::DecompPalARGB565(std::uint8_t*d,const std::uint8_t*s,unsigned n)const{for(unsigned i=0;i<n;++i){auto&p=m_header.extended.palette[s[i]];std::uint16_t v=(p.b>>3)|((p.g>>2)<<5)|((p.r>>3)<<11);std::memcpy(d+i*2,&v,2);}}
int CBLPFile::DecompPal(PIXEL_FORMAT f,unsigned l,std::uint8_t*d,const std::uint8_t*s)const{unsigned n=std::max(1u,m_header.width>>l)*std::max(1u,m_header.height>>l);switch(f){case PIXEL_ARGB8888:DecompPalARGB8888(d,s,n);return 1;case PIXEL_ARGB4444:DecompPalARGB4444(d,s,n);return 1;case PIXEL_ARGB1555:DecompPalARGB1555(d,s,n);return 1;case PIXEL_RGB565:DecompPalARGB565(d,s,n);return 1;default:return 0;}}
PIXEL_FORMAT CBLPFile::Lock(BlitFormat f,unsigned l,std::uint8_t**d,unsigned*stride){if(!d||!IsValidMip(l))return PIXEL_UNSPECIFIED;PIXEL_FORMAT pf=f==BlitFormat_Argb8888?PIXEL_ARGB8888:f==BlitFormat_Argb4444?PIXEL_ARGB4444:f==BlitFormat_Argb1555?PIXEL_ARGB1555:f==BlitFormat_Rgb565?PIXEL_RGB565:f==BlitFormat_Dxt1?PIXEL_DXT1:f==BlitFormat_Dxt3?PIXEL_DXT3:f==BlitFormat_Dxt5?PIXEL_DXT5:static_cast<PIXEL_FORMAT>(m_header.preferredFormat);if(m_images){*d=reinterpret_cast<std::uint8_t*>(Image(l));if(stride)*stride=std::max(1u,m_header.width>>l)*4;return PIXEL_ARGB8888;}auto*s=static_cast<std::uint8_t*>(m_inMemoryImage)+m_header.mipOffsets[l];if(m_header.colorEncoding==2&&(pf==PIXEL_DXT1||pf==PIXEL_DXT3||pf==PIXEL_DXT5)){*d=s;if(stride)*stride=0;return pf;}unsigned size=0;if(!GetFormatSize(pf,l,&size,stride))return PIXEL_UNSPECIFIED;m_lockDecompMem=static_cast<std::uint8_t*>(std::malloc(size));if(!m_lockDecompMem)return PIXEL_UNSPECIFIED;if(m_header.colorEncoding!=1||!DecompPal(pf,l,m_lockDecompMem,s)){std::free(m_lockDecompMem);m_lockDecompMem=nullptr;return PIXEL_UNSPECIFIED;}*d=m_lockDecompMem;return pf;}
int CBLPFile::Unlock(unsigned l){int ok=IsValidMip(l);if(m_lockDecompMem){std::free(m_lockDecompMem);m_lockDecompMem=nullptr;}return ok;}
int CBLPFile::Lock2(PIXEL_FORMAT f,unsigned l,std::uint8_t*d,unsigned*stride){if(!d||!IsValidMip(l))return 0;if(m_images){unsigned size=0;if(!GetFormatSize(PIXEL_ARGB8888,l,&size,stride))return 0;std::memcpy(d,Image(l),size);return 1;}auto*s=static_cast<std::uint8_t*>(m_inMemoryImage)+m_header.mipOffsets[l];if(m_header.colorEncoding==2&&(f==PIXEL_DXT1||f==PIXEL_DXT3||f==PIXEL_DXT5)){std::memcpy(d,s,m_header.mipSizes[l]);if(stride)*stride=0;return 1;}return m_header.colorEncoding==1&&DecompPal(f,l,d,s)&&GetFormatSize(f,l,&l,stride);}
int CBLPFile::Unlock2(unsigned l){return IsValidMip(l);}int CBLPFile::LockChain(PIXEL_FORMAT f,MipBits**out,unsigned l){if(!out||l>=m_numLevels)return 0;*out=m_images;return f==PIXEL_ARGB8888&&m_images;}int CBLPFile::LockChain2(PIXEL_FORMAT f,MipBits**out,unsigned l){return LockChain(f,out,l);}unsigned CBLPFile::Bytes()const{return Bytes(0);}unsigned CBLPFile::Bytes(unsigned l)const{if(l>=16)return 0;if(m_header.colorEncoding==2)return m_header.mipSizes[l];unsigned n=0,s=0;GetFormatSize(PIXEL_ARGB8888,l,&n,&s);return n;}
